-- The Marketing area (docs/marketing-plan.md §4.3; docs/plan.md §1.72, M43): the Marketing pack's
-- tables for measuring a client's website, Mezonas's own mezonas.com first. Ported from Plenary
-- Labs' 0085 and 0086 (copied, not shared), with tenant_id and site_id on every row and a site's
-- goals in place of a waitlist sign-up. New tables only, so the previous Worker keeps working.
-- Generated by drizzle-kit from packs/marketing/src/schema.ts; the grants, row-level security and
-- pack comments at the end are hand-written.
--
--   site               A client's measured website: domain, name, goals (tracked elements whose
--                      click is the visit's goal), on or off.
--   site_salt          The day's random salt for a site's visit hash; deleted once its day is over.
--   site_event         One thing a page reported. Raw; kept 90 days.
--   site_visit         One visit (one browser, one UTC day), built nightly. Kept 13 months.
--   site_daily_*       Daily totals per page, per tracked element and per visit dimension. Kept.
--   site_bot_daily     Requests not counted, per day and reason.
--
-- Never stored: an IP address, a user agent string, a cookie, or an identifier that outlives a
-- UTC day. A visit's times are to the hour, and nothing joins a visit to a person.
--
-- Rollback: drop the eight tables. Nothing else references them.
CREATE TABLE "site" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"domain" text NOT NULL,
	"name" text NOT NULL,
	"goals" text[] DEFAULT '{}'::text[] NOT NULL,
	"status" text DEFAULT 'on' NOT NULL,
	"created_by_user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "site_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "site_domain_key" UNIQUE("tenant_id","domain"),
	CONSTRAINT "site_status_check" CHECK ("site"."status" in ('on', 'off')),
	CONSTRAINT "site_domain_check" CHECK ("site"."domain" ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' and "site"."domain" !~ '^www\.'),
	CONSTRAINT "site_goals_check" CHECK (cardinality("site"."goals") <= 20)
);
