	"city" text,
	"time_zone" text,
	"device" text,
	"browser" text,
	"os" text,
	"language" text,
	"engaged_ms" integer,
	"scroll" integer,
	"target" text,
	"position" integer,
	"form" text,
	CONSTRAINT "site_event_kind" CHECK ("site_event"."kind" in ('view', 'engage', 'click', 'form_seen')),
	CONSTRAINT "site_event_path" CHECK (left("site_event"."path", 1) = '/' and length("site_event"."path") <= 512),
	CONSTRAINT "site_event_visit_hex" CHECK ("site_event"."visit" ~ '^[0-9a-f]{32}$'),
	CONSTRAINT "site_event_source_group" CHECK ("site_event"."source_group" is null or "site_event"."source_group" in ('direct', 'search', 'social', 'referral', 'campaign', 'internal')),
	CONSTRAINT "site_event_device" CHECK ("site_event"."device" is null or "site_event"."device" in ('phone', 'tablet', 'desktop')),
	CONSTRAINT "site_event_country" CHECK ("site_event"."country" is null or "site_event"."country" ~ '^[A-Z]{2}$'),
	CONSTRAINT "site_event_ranges" CHECK (("site_event"."engaged_ms" is null or "site_event"."engaged_ms" between 0 and 3600000)
        and ("site_event"."scroll" is null or "site_event"."scroll" between 0 and 4)
        and ("site_event"."position" is null or "site_event"."position" between 0 and 100)),
	CONSTRAINT "site_event_kind_fields" CHECK (case "site_event"."kind"
        when 'view' then "site_event"."source_group" is not null and "site_event"."device" is not null
        when 'engage' then "site_event"."engaged_ms" is not null and "site_event"."scroll" is not null
        when 'click' then "site_event"."target" is not null and "site_event"."position" is not null
        when 'form_seen' then "site_event"."form" is not null
        else false end)
);
