-- The runtime rebuilds a finished day by deleting and inserting its visits and totals, and the
-- nightly sweep deletes past the retention limits and every salt whose day is over, so these
-- tables (unlike the platform's history, invariant 3) give the runtime DELETE. Nothing is
-- rewritten in place but a site's settings and the bot counter.
GRANT SELECT, INSERT, UPDATE ON site TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT, DELETE ON site_salt, site_event, site_visit, site_daily_page, site_daily_click, site_daily_total TO cs_runtime;
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON site_bot_daily TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['site', 'site_salt', 'site_event', 'site_visit', 'site_daily_page', 'site_daily_click', 'site_daily_total', 'site_bot_daily'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
    -- Which pack owns a table: the platform's migration test checks pack tables for RLS and
    -- leaves their columns to the pack's own test (docs/plan.md §1.12, §1.63).
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:marketing');
  END LOOP;
END
$$;
